      "html_path": "works/gregory-nazianzus-oration-28/index.html#p-5",
      "label": "제2신학강론 (제28강론) 5",
      "location": "5",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:a935c86104ef504b1821e2fa473acac6811e6a5000f66713fdfbad3adc066ebd",
        "text": "Τοῦτο μὲν οὖν ἐνταῦθα κείσθω· τὸ δὲ ἡμέτερον, οὐχ ἡ εἰρήνη τοῦ θεοῦ μόνον ὑπερέχει πάντα νοῦν καὶ κατάληψιν, οὐδὲ ὅσα τοῖς δικαίοις ἐστὶν ἐν ἐπαγγελίαις ἀποκείμενα, τὰ μήτε ὀφθαλμοῖς ὁρατά, μήτε ὠσὶν ἀκουστά, μήτε διανοίᾳ θεωρητά, κατὰ μικρὸν γοῦν, οὐδὲ ἡ τῆς κτίσεως ἀκριβὴς κατανόησις· καὶ γὰρ καὶ ταύτης πείσθητι τὰς σκιὰς ἔχειν μόνον, ὅταν ἀκούσῃς· ὄψομαι τοὺς οὐρανούς, ἔργα τῶν δακτύλων σου, σελήνην καὶ ἀστέρας, καὶ τὸν ἐν αὐτοῖς πάγιον λόγον· ὡς οὐχὶ νῦν ὁρῶν, ὀψόμενος δὲ ἔστιν ὅτε· ἀλλὰ πολὺ πρὸ τούτων ἡ ὑπὲρ ταῦτα, καὶ ἐξ ἧς ταῦτα, φύσις ἄληπτός τε καὶ ἀπερίληπτος· λέγω δέ, οὐχ ὅτι ἔστιν, ἀλλ’ ἥτις ἐστίν. οὐ γὰρ κενὸν τὸ κήρυγμα ἡμῶν, οὐδὲ ματαία ἡ πίστις ἡμῶν, οὐδὲ τοῦτό ἐστιν ὃ δογματίζομεν· μὴ πάλιν τὴν εὐγνωμοσύνην ἡμῶν ἀθείας λάβῃς ἀρχὴν καὶ συκοφαντίας, καὶ κατεπαρθῇς ὡς ὁμολογούντων τὴν ἄγνοιαν. πλεῖστον γὰρ διαφέρει τοῦ εἶναί τι πεπεῖσθαι τὸ τί ποτέ ἐστι τοῦτο εἰδέναι."
      },
      "title": "제2신학강론 (제28강론)",
      "translation": {
        "notes": [
          "하나님의 평화는 빌립보서 4:7, 눈과 귀와 마음에 이르지 못한 약속은 고린도전서 2:9, 하늘과 달과 별은 시편 8:3의 표현과 연결된다. 성경의 말은 강론에 실린 그리스어 형태를 따른다.",
          "하나님께서 계신다는 사실과 그분이 무엇이신지를 구별한다. 본성을 파악하지 못한다는 설명을 믿음과 선포의 무의미함에 연결하려는 상대의 반론에 답한다."
        ],
        "revision_id": "sha256:d5e381d9209f887e3c742fa7881cd9636f0b38d92c997550fde8ed5106d26a8c",
        "text": "이 문제는 여기까지 두자. 우리에게는 하나님의 평화만 모든 지성과 이해를 뛰어넘는 것이 아니다. 의로운 이들에게 약속으로 마련된 것들도 그러하다. 그것들은 눈으로 보거나 귀로 듣거나 생각으로 살필 수 없으며, 조금도 그럴 수 없다. 창조를 정확히 이해하는 일도 그러하다. 우리는 창조에 대해서도 그림자만 붙들고 있다는 사실을, 다음 말을 들을 때 인정하라. “나는 주님의 손가락으로 만드신 하늘들, 달과 별들, 그리고 그 안의 확고한 질서를 보리라.” 지금 보는 것이 아니라, 언젠가 보게 될 것이라는 말이다. 이보다 훨씬 더, 이 모든 것을 뛰어넘고 이 모든 것의 근원이 되는 본성은 붙잡을 수도 담아낼 수도 없다. 나는 하나님께서 존재하신다는 사실이 아니라, 그분이 무엇이신지를 말한다. 우리의 선포가 헛되거나 믿음이 무의미한 것도 아니며, 그런 가르침을 내놓는 것도 아니기 때문이다. 우리의 솔직함을 다시 무신론과 비방의 빌미로 삼지 말라. 우리가 무지를 인정했다며 우쭐대지 말라. 어떤 것이 존재한다고 확신하는 일과 그것이 무엇인지 아는 일은 크게 다르기 때문이다."
      },
      "work_id": "gregory-nazianzus-oration-28",
      "work_passage_id": "gregory-nazianzus-oration-28:5"
