      "html_path": "works/gregory-nazianzus-oration-28/index.html#p-9",
      "label": "제2신학강론 (제28강론) 9",
      "location": "9",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:35b0b8cd7c43e1c2cea335e67e654c0e7ca941eaeae73e908224efcc2856014d",
        "text": "Οὕτω μὲν οὖν οὐ σῶμα ἡμῖν ὁ θεός. οὐδὲ γὰρ ἤδη τις τοῦτο τῶν θεοπνεύστων ἢ εἶπεν ἢ παρεδέξατο, οὐδὲ τῆς ἡμετέρας αὐλῆς ὁ λόγος. λείπεται δὴ ἀσώματον ὑπολαμβάνειν. ἀλλ’ εἰ ἀσώματον, οὔπω μὲν οὐδὲ τοῦτο τῆς οὐσίας παραστατικόν τε καὶ περιεκτικόν, ὥσπερ οὐδὲ τὸ ἀγέννητον, καὶ τὸ ἄναρχον, καὶ τὸ ἀναλλοίωτον, καὶ τὸ ἄφθαρτον, καὶ ὅσα περὶ θεοῦ ἢ περὶ θεὸν εἶναι λέγεται. τί γὰρ ὄντι αὐτῷ κατὰ τὴν φύσιν καὶ τὴν ὑπόστασιν ὑπάρχει τὸ μὴ ἀρχὴν ἔχειν, μηδὲ ἐξίστασθαι, μηδὲ περατοῦσθαι; ἀλλ’ ὅλον τὸ εἶναι περιλαμβάνειν λείπεται προσφιλοσοφεῖν τε καὶ προσεξετάζειν τῷ γε νοῦν θεοῦ ἀληθῶς ἔχοντι καὶ τελεωτέρῳ τὴν θεωρίαν. ὡς γὰρ οὐκ ἀρκεῖ τὸ σῶμα εἰπεῖν, ἢ τὸ γεγεννῆσθαι, πρὸς τὸ καὶ τό, περὶ ὃ ταῦτα, παραστῆσαί τε καὶ δηλῶσαι, ἀλλὰ δεῖ καὶ τὸ ὑποκείμενον τούτοις εἰπεῖν, εἰ μέλλοι τελείως καὶ ἀποχρώντως τὸ νοούμενον παραστήσεσθαι· ἢ γὰρ ἄνθρωπος ἢ βοῦς ἢ ἵππος τοῦτο τὸ ἐνσώματον καὶ γεννώμενον καὶ φθειρόμενον· οὕτως οὐδὲ ἐκεῖ στήσεται μέχρι τοῦ εἰπεῖν ἃ μή ἐστιν ὁ τὴν τοῦ ὄντος πολυπραγμονῶν φύσιν, ἀλλὰ δεῖ, πρὸς τῷ εἰπεῖν ἃ μή ἐστι, καὶ ὅ ἐστιν εἰπεῖν, ὅσῳ καὶ ῥᾶον ἕν τι περιλαβεῖν, ἢ τὰ πάντα καθ᾿ ἕκαστον ἀπειπεῖν, - ἵνα ἔκ τε τῆς ἀναιρέσεως ὧν οὔκ ἐστι, καὶ τῆς οὗ ἐστὶ θέσεως, περιληφθῇ τὸ νοούμενον. ὁ δὲ ἃ μὲν οὔκ ἐστι λέγων, σιωπῶν δὲ ὅ ἐστι, ποιεῖ παραπλήσιον, ὥσπερ ἂν εἰ τὰ πέντε δὶς ὅσα ἐστὶν ἐρωτώμενος ὅτι μὲν οὐ δύο λέγοι, οὐδὲ τρεῖς, οὐδὲ τέσσαρες, οὐδὲ πέντε, οὐδὲ εἴκοσιν, οὐδὲ τριάκοντα, οὐδέ τινα, ἵνα συνελὼν εἴπω, τῶν ἐντὸς δεκάδος ἢ δεκαδικῶν ἀριθμῶν· ὅτι δὲ εἴη δέκα μὴ λέγοι, μηδὲ ἐρείδοι τὸν νοῦν τοῦ ἐρωτῶντος εἰς τὸ ζητούμενον. πολλῷ γὰρ ῥᾷον καὶ συντομώτερον ἐκ τοῦ ὅ ἐστιν ὅσα οὔκ ἐστι δηλῶσαι, ἢ ἐκ τοῦ ἀνελεῖν ἃ μή ἐστιν ὅ ἐστιν ἐνδείξασθαι. Ἢ τοῦτο μὲν παντὶ δῆλον."
      },
      "title": "제2신학강론 (제28강론)",
      "translation": {
        "notes": [
          "ἀσώματον(몸이 없음), ἀγέννητον(나지 않음), ἄναρχον(시작이 없음) 등은 무엇이 아닌지를 밝히는 성질들이다. 이 대목의 ὑπόστασις는 본성과 함께 존재의 바탕을 가리키므로 ‘존재 자체’로 옮겼다.",
          "다섯의 두 배라는 예는 수를 차례로 부정하는 일과 열이라는 답을 주는 일을 비교한다. 두 배가 아니라는 말이 아니라, 질문에 대한 답을 계속 피하는 상황이다."
        ],
        "revision_id": "sha256:f792913b1ecfb73a8051fcdd98f77990460cbe6d759909c2f4566df751d643bf",
        "text": "그러므로 우리에게 하나님은 몸이 아니시다. 하나님의 영감을 받은 이들 가운데 아무도 몸이라고 말하거나 받아들인 적이 없으며, 그런 말은 우리 공동체에 속하지도 않는다. 이제 몸이 없다고 생각하는 길이 남는다. 그러나 몸이 없다고 해도, 이것 역시 본질을 밝히거나 그 안에 담아내는 말은 아직 아니다. 나지 않으셨다거나, 시작이 없다거나, 변하지 않는다거나, 썩지 않는다는 말도 마찬가지다. 하나님에 관하여 말하거나 하나님께 속한다고 말하는 다른 성질들도 그렇다. 본성과 존재 자체로 무엇이시기에, 그분께는 시작도 변화도 끝도 없다는 성질이 있는가? 하나님을 참으로 생각하고 더 온전히 관조하는 사람에게는, 그분의 존재 전체를 파악하는 일이 더 논하고 살펴야 할 과제로 남아 있다. 몸이라거나 태어났다고 말하는 것만으로는, 이런 성질을 가진 대상 자체를 밝혀 알리기에 충분하지 않다. 그 대상을 온전하고 충분하게 밝히려면, 이런 성질들의 바탕이 되는 것까지 말해야 한다. 몸을 지니고 태어나고 죽는 그것이 사람인지, 소인지, 말인지를 말해야 한다. 이와 같이 하나님의 본성을 파고드는 사람도, 하나님께서 무엇이 아니신지를 말하는 데서 멈출 수 없다. 그분이 무엇이 아니신지를 말하는 데 더하여, 무엇이신지도 말해야 한다. 다른 모든 것을 하나씩 부정하는 것보다, 한 대상을 파악하는 편이 더 쉽기 때문이다. 무엇이 아닌지를 부정하고 무엇인지를 긍정함으로써, 생각하는 대상을 파악해야 한다. 무엇이 아닌지만 말하고 무엇인지에는 침묵하는 이는 다음과 같은 일을 하는 셈이다. 다섯의 두 배가 얼마인지 질문받고, 둘이 아니라고 말하며, 셋도 넷도 다섯도 아니고, 스물도 서른도 아니라고 말하는 것이다. 요컨대 열보다 작은 수나 열의 배수 가운데 어떤 수도 아니라고 말하면서, 열이라고는 말하지 않고, 질문한 사람의 생각이 찾던 답에 닿도록 해 주지 않는 것이다. 무엇인지를 말해 무엇이 아닌지를 밝히는 편이 훨씬 쉽고 짧다. 무엇이 아닌지를 부정해서 무엇인지를 드러내는 일보다 그렇다. 이 점은 누구에게나 분명하지 않은가?"
      },
      "work_id": "gregory-nazianzus-oration-28",
      "work_passage_id": "gregory-nazianzus-oration-28:9"
