      "html_path": "works/gregory-nazianzus-oration-28/index.html#p-20",
      "label": "제2신학강론 (제28강론) 20",
      "location": "20",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:be0491aa5c9f6c4f8cfcd0fcd0eb81d2317890fe535f408de7c5f5da847f5cd7",
        "text": "Παύλῳ δὲ εἰ μὲν ἔκφορα ἦν ἃ παρέσχεν ὁ τρίτος οὐρανός, καὶ ἡ μέχρις ἐκείνου πρόοδος ἢ ἀνάβασις ἢ ἀνάληψις, τάχα ἄν τι περὶ θεοῦ πλέον ἔγνωμεν, εἴπερ τοῦτο ἦν τὸ τῆς ἁρπαγῆς μυστήριον. ἐπεὶ δὲ ἄρρητα ἦν, καὶ ἡμῖν σιωπῇ τιμάσθω. τοσοῦτον δὲ ἀκούσωμεν αὐτοῦ Παύλου λέγοντος, ὅτι ἐκ μέρους γινώσκομεν, καὶ ἐκ μέρους προφητεύομεν. ταῦτα καὶ τὰ τοιαῦτα ὁμολογεῖ ὁ μὴ ἰδιώτης τὴν γνῶσιν, ὁ δοκιμὴν ἀπειλῶν τοῦ ἐν αὐτῷ λαλοῦντος χριστοῦ, ὁ μέγας τῆς ἀληθείας προαγωνιστὴς καὶ διδάσκαλος· καὶ πᾶσαν τὴν κάτω γνῶσιν οὐδὲν ὑπὲρ τὰ ἔσοπτρα καὶ τὰ αἰνίγματα τίθεται, ὡς ἐν μικροῖς τῆς ἀληθείας ἱσταμένην ἰνδάλμασιν. εἰ δὲ μὴ λίαν δοκῶ τισὶ περιττὸς καὶ περίεργος τὰ τοιαῦτα ἐξετάζων, οὐδὲ ἄλλα τινὰ τυχὸν ἢ ταῦτα ἦν, ἃ μὴ δύναται νῦν βασταχθῆναι, ἅπερ ὁ Λόγος αὐτὸς ὑπῃνίσσετο, ὥς ποτε βασταχθησόμενα καὶ τρανωθησόμενα· καὶ ἃ μηδ’ ἂν αὐτὸν δυνηθῆναι χωρῆσαι τὸν κάτω κόσμον Ἰωάννης ὁ τοῦ Λόγου πρόδρομος ἡ μεγάλη τῆς ἀληθείας φωνή, διωρίζετο."
      },
      "title": "제2신학강론 (제28강론)",
      "translation": {
        "notes": [
          "셋째 하늘은 고린도후서 12:2-4, 부분적 앎과 예언은 고린도전서 13:9, 거울과 수수께끼는 13:12와 연결된다. ‘지식에 무지하지 않다’는 고린도후서 11:6, 그리스도의 증거는 13:3의 표현이다.",
          "감당할 수 없는 것들은 요한복음 16:12, 세계가 담을 수 없다는 말은 21:25와 연결된다. Mason은 ‘말씀의 선구자’라는 호칭에 세례 요한과 복음서 저자의 지칭이 겹쳐 있다고 설명한다(52쪽)."
        ],
        "revision_id": "sha256:cd03c1103ae4c4fcddcf2e58b64b79157f1da031c168173334d0ae787f484c09",
        "text": "셋째 하늘과 거기까지의 전진, 또는 올라감과 들려 올라감이 바울에게 준 것들을 말할 수 있었다면, 우리는 하나님에 관해 조금 더 알았을 것이다. 그 들려 올라감의 신비가 바로 그것에 관한 것이었다면 말이다. 그러나 말할 수 없는 것들이었으니, 우리도 침묵으로 그것을 기리자. 바울 자신이 말한 것 가운데 이만큼만 듣자. “우리는 부분적으로 알고, 부분적으로 예언한다.” 지식에 무지한 사람이 아닌 이가 이런 말들을 고백한다. 자기 안에서 말씀하시는 그리스도의 증거를 내세우는 이, 진리를 위해 앞장서 싸우는 위대한 교사가 그렇게 말한다. 그는 이 땅의 모든 지식을 거울과 수수께끼 이상으로 여기지 않는다. 진리의 작은 형상들에 머물러 있다고 보기 때문이다. 이런 것을 살피는 내가 어떤 이들에게 너무 유별나고 지나치게 따지는 사람처럼 보이지 않는다면, 어쩌면 다음 말씀도 바로 이런 것들을 말한 것일 수 있다. 지금은 감당할 수 없는 것들이 있다고 말씀 자신이 암시하셨으며, 언젠가는 감당하고 분명히 알게 되리라고 하셨다. 말씀의 선구자요 진리를 전하는 큰 음성인 요한이, 이 땅의 세계 자체도 그것들을 담을 수 없을 것이라고 밝힌 것 역시 이런 것들일 수 있다."
      },
      "work_id": "gregory-nazianzus-oration-28",
      "work_passage_id": "gregory-nazianzus-oration-28:20"
