      "html_path": "works/gregory-nazianzus-oration-28/index.html#p-21",
      "label": "제2신학강론 (제28강론) 21",
      "location": "21",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:546b99221a5051e963e9e5863f2793d7cd4769d9ab8d540a3cfa564a797687a3",
        "text": "Πᾶσα μὲν οὖν ἀλήθεια καὶ πᾶς λόγος δυστέκμαρτός τε καὶ δυσθεώρητος· καὶ οἷον ὀργάνῳ μικρῷ μεγάλα δημιουργοῦμεν, τῇ ἀνθρωπίνῃ σοφίᾳ τὴν τῶν ὄντων γνῶσιν θηρεύοντες, καὶ τοῖς νοητοῖς προσβάλλοντες μετὰ τῶν αἰσθήσεων, ἢ οὐκ ἄνευ αἰσθήσεων, ὑφ’ ὧν περιφερόμεθα καὶ πλανώμεθα, καὶ οὐκ ἔχομεν γυμνῷ τῷ νοὶ γυμνοῖς τοῖς πράγμασιν ἐντυγχάνοντες μᾶλλόν τι προσιέναι τῇ ἀληθείᾳ, καὶ τὸν νοῦν τυποῦσθαι ταῖς καταλήψεσιν. ὁ δὲ περὶ θεοῦ λόγος, ὅσῳ τελεώτερος, τοσούτῳ δυσεφικτότερος, καὶ πλείους τὰς ἀντιλήψεις ἔχων καὶ τὰς λύσεις ἐργωδεστέρας. πᾶν γὰρ τὸ ἐνιστάμενον, κἂν βραχύτατον ᾖ, τὸν τοῦ λόγου δρόμον ἐπέσχε καὶ διεκώλυσε, καὶ τὴν εἰς τὸ πρόσω φορὰν διέκοψεν· ὥσπερ οἱ τοὺς ἵππους τοῖς ῥυτῆρσιν ἀθρόως μεθέλκοντες φερομένους, καὶ τῷ ἀδοκήτῳ τοῦ τιναγμοῦ περιτρέποντες. οὕτω Σολομὼν μέν, ὁ σοφισάμενος περισσὰ ὑπὲρ πάντας τοὺς γενομένους ἔμπροσθεν καὶ καθ’ ἑαυτόν, ᾧ τὸ τῆς καρδίας πλάτος δῶρον θεοῦ, καὶ ἡ ψάμμου δαψιλεστέρα χύσις τῆς θεωρίας, ὅσῳ πλέον ἐμβατεύει τοῖς βάθεσι, τοσούτῳ πλέον ἰλιγγιᾷ, καὶ τέλος τι ποιεῖται σοφίας εὑρεῖν ὅσον διέφυγεν. Παῦλος δὲ πειρᾶται μὲν ἐφικέσθαι, οὔπω λέγω τῆς τοῦ θεοῦ φύσεως, τοῦτο γὰρ ᾔδει παντελῶς ἀδύνατον ὄν, ἀλλὰ μόνον τῶν τοῦ θεοῦ κριμάτων· ἐπεὶ δὲ οὐχ εὑρίσκει διέξοδον οὐδὲ στάσιν τῆς ἀναβάσεως, οὐδὲ εἴς τι φανερὸν τελευτᾷ πέρας ἡ πολυπραγμοσύνη τῆς διανοίας, ἀεί τινος ὑποφαινομένου τοῦ λείποντος· ὢ τοῦ θαύματος (ἵνα καὶ αὐτὸς πάθω τὸ ἴσον)· ἐκπλήξει περιγράφει τὸν λόγον, καὶ πλοῦτον θεοῦ καὶ βάθος τὸ τοιοῦτο καλεῖ, καὶ ὁμολογεῖ τῶν τοῦ θεοῦ κριμάτων τὸ ἀκατάληπτον, μονονουχὶ τὰ αὐτὰ τῷ Δαβὶδ φθεγγόμενος, ποτὲ μὲν ἄβυσσον πολλὴν ὀνομάζοντι τὰ τοῦ θεοῦ κρίματα, ἧς οὐκ ἔστι τὴν ἕδραν ἢ μέτρῳ ἢ αἰσθήσει λαβεῖν, ποτὲ δὲ τεθαυμαστῶσθαι τὴν γνῶσιν ἐξ ἑαυτοῦ καὶ τῆς ἑαυτοῦ συστάσεως λέγοντι, κεκραταιῶσθαί τε πλέον ἢ κατὰ τὴν ἑαυτοῦ δύναμιν καὶ περίδραξιν."
      },
      "title": "제2신학강론 (제28강론)",
      "translation": {
        "notes": [
          "솔로몬의 지혜는 열왕기상 3:12와 4:29-31, 끝없이 탐구하는 지혜는 전도서 7:23-24와 연결된다. 바울의 풍요와 깊이는 로마서 11:33의 탄성이다.",
          "큰 심연은 시편 36:6, 너무 높은 지식은 시편 139:6을 활용한다. 하나님을 파악하려는 어려움에서 인간 자신을 이해하는 어려움으로 논의를 잇는다."
        ],
        "revision_id": "sha256:ca30c5e0bba6f47804a724e6d2842fb9f26985381e9a9f658a687d907fc10702",
        "text": "모든 진리와 모든 논의는 헤아리기도 살펴보기도 어렵다. 우리는 작은 도구로 큰 것을 만드는 셈이다. 인간의 지혜로 존재하는 것들의 지식을 찾아다니며, 감각을 동반하여 지성의 대상들에 다가간다. 적어도 감각 없이 다가가지는 못하며, 그 감각들 때문에 휘둘리고 길을 잃는다. 지성만으로 대상 자체를 만나 진리에 더 가까이 다가가거나, 파악한 것들로 지성을 빚어 낼 수도 없다. 하나님에 관한 논의는 더 온전할수록 도달하기가 더 어렵고, 장애는 더 많으며 해결은 더 힘들다. 가로막는 것은 아무리 작은 것이라도, 논의의 달리는 길을 붙들어 막고 앞으로 나아가는 운동을 끊기 때문이다. 달리는 말의 고삐를 갑자기 잡아당겨, 뜻밖의 충격으로 말을 넘어뜨리는 것과 같다. 자신보다 앞선 이들과 동시대의 모든 이보다 훨씬 지혜로웠던 솔로몬도 그러했다. 그는 넓은 마음과 모래보다 더 풍성한 관조를 하나님께 선물로 받았다. 그러나 깊은 곳에 더 들어갈수록 더 어지러워졌고, 얼마나 많은 것이 자기를 벗어났는지 발견하는 일을 지혜의 어떤 완성으로 삼았다. 바울도 도달하려고 힘썼다. 하나님의 본성에 도달하려 했다는 말은 아직 하지 않겠다. 그것이 완전히 불가능함을 알고, 하나님의 판단들에만 도달하려 했다. 그러나 출구도, 올라감이 멈추는 지점도 찾지 못했다. 생각의 탐구가 분명한 어떤 끝에 이르지도 못했다. 알지 못한 것이 언제나 어렴풋이 나타났기 때문이다. 오, 얼마나 놀라운가! 나도 바울과 같은 마음이 된다. 그는 놀라움으로 논의를 마치며, 이것을 하나님의 풍요와 깊이라고 불렀다. 하나님의 판단들은 파악할 수 없다고 고백했다. 다윗과 거의 같은 말을 한 것이다. 다윗은 하나님의 판단들을 큰 심연이라고 부르기도 했으며, 그 바닥은 척도로도 감각으로도 붙잡을 수 없다고 했다. 또 자기 자신과 자기의 구성을 살피니 지식이 너무도 놀라워, 자기의 능력과 이해보다 훨씬 더 크다고 말하기도 했다."
      },
