      "html_path": "works/gregory-nazianzus-oration-31/index.html#p-33",
      "label": "제5신학강론 (제31강론) 33",
      "location": "33",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:af48b540633fe2d674ce068732a7550727ee4c40a7a65adbba00350425417827",
        "text": "Ἀλλ’ οὐδὲ τοῦτο θέσθαι δυνατὸν ἐμοί, δι’ ἓν μέν, ὅτι τὴν μὲν τὸ κινῆσαν καὶ πάνυ δῆλον· θεοῦ δὲ οὐδὲν πρεσβύτερον, ἵν’ ᾖ τι τὸ τοῦτον κεκινηκός. αὐτὸς μὲν γὰρ πάντων αἰτία, αἰτίαν δὲ πρεσβυτέραν οὐκ ἔχει. δεύτερον δέ, ὅτι κἀνταῦθα τῶν αὐτῶν ὑπόνοια, συνθέσεως, χύσεως, ἀστάτου καὶ οὐ παγίας φύσεως, ὧν οὐδὲν ἐννοητέον περὶ θεότητος. καὶ ὅλως οὐδὲν ἔστιν ὅ μοι τὴν διάνοιαν ἵστησιν ἐπὶ τῶν ὑποδειγμάτων θεωροῦντι τὸ φανταζόμενον, πλὴν εἴ τις ἕν τι λαβὼν τῆς εἰκόνος, ὑπ’ εὐγνωμοσύνης τὰ λοιπὰ ῥίψειε. τέλος οὖν ἔδοξέ μοι κράτιστον εἶναι τὰς μὲν εἰκόνας χαίρειν ἐᾶσαι καὶ τὰς σκιάς, ὡς ἀπατηλὰς καὶ τῆς ἀληθείας πλεῖστον ἀποδεούσας, αὐτὸν δὲ τῆς εὐσεβεστέρας ἐννοίας ἐχόμενον, ἐπ’ ὀλίγων ῥημάτων ἱστάμενον, ὁδηγῷ τῷ πνεύματι χρώμενον, ἣν ἐντεῦθεν ἔλλαμψιν ἐδεξάμην, ταύτην εἰς τέλος διαφυλάσσοντα, ὡς γνησίαν κοινωνὸν καὶ συνόμιλον, τὸν αἰῶνα τοῦτον διαπορεύεσθαι διατέμνοντα, καὶ τοὺς ἄλλους πείθειν εἰς δύναμιν προσκυνεῖν πατέρα, καὶ υἱόν, καὶ πνεῦμα ἅγιον, τὴν μίαν θεότητά τε καὶ δύναμιν· ὅτι αὐτῷ πᾶσα δόξα, τιμή, κράτος, εἰς τοὺς αἰῶνας τῶν αἰώνων· Ἀμήν."
      },
      "title": "제5신학강론 (제31강론)",
      "translation": {
        "notes": [
          "반짝임의 원인이 분명하다는 점과 하나님에게는 더 앞선 원인이 없다는 점을 비교한다. 합성, 흐름, 불안정함을 신성에 적용하는 문제도 다시 제시한다.",
          "비유의 한 부분을 분별 있게 쓰는 경우를 허용한 뒤, 성령의 안내와 받은 비춤을 지키며 살아가겠다고 말한다. 아버지와 아들과 성령, 하나의 신성과 능력께 경배하는 고백으로 강론을 마친다."
        ],
        "revision_id": "sha256:097dfc1065bb1cf26d5414f27e2df28e0abb584d360b936d8423f1e363bee268",
        "text": "그러나 나는 이것도 받아들일 수 없다. 먼저, 그 반짝임을 움직인 것은 아주 분명하다. 그러나 하나님보다 앞선 것은 아무것도 없어서, 그분을 움직인 어떤 것도 있을 수 없다. 그분 자신이 모든 것의 원인이시며, 더 앞선 원인을 가지시지 않기 때문이다. 다음으로, 여기에도 같은 생각들, 곧 합성과 흐름, 안정되지 않고 굳건하지 않은 본성이라는 생각이 있다. 이 가운데 어느 것도 신성에 관하여 생각해서는 안 된다. 전체적으로 보면, 비유들에서 떠오르는 것을 살펴도 내 생각을 안정되게 붙잡아 주는 것은 아무것도 없다. 다만 누군가 분별 있게 비유의 한 부분만 받아들이고 나머지는 버린다면 다르다. 그러므로 마침내 나는 형상들과 그림자들을 떠나보내는 것이 가장 좋겠다고 생각했다. 그것들은 오해를 일으키며 진리에서 매우 멀리 떨어져 있기 때문이다. 나는 더 경건한 생각을 붙들고, 적은 말들에 머물며, 성령을 안내자로 삼고, 거기에서 받은 비춤을 끝까지 지키면서, 그 빛을 참된 벗과 동반자로 삼아 이 시대를 지나가기로 했다. 또 힘을 다해 다른 이들도 아버지와 아들과 성령, 곧 하나의 신성과 능력께 경배하도록 설득하기로 했다. 모든 영광과 존경과 권능이 그분께 영원토록 있기를. 아멘."
      },
      "work_id": "gregory-nazianzus-oration-31",
      "work_passage_id": "gregory-nazianzus-oration-31:33"
