      "html_path": "works/athanasius-incarnation/index.html#p-57-1",
      "label": "말씀의 성육신에 관하여 57.1",
      "location": "57.1",
      "relation": "related_testimony",
      "source": {
        "language": "grc",
        "revision_id": "sha256:8c2d2de519088b220c73540aea28d5fa46c9d01ccabd6f5c36c7fd0daf3a1c4e",
        "text": "Ἀλλὰ πρὸς τὴν ἐκ τῶν γραφῶν ἔρευναν καὶ γνῶσιν ἀληθῆ, χρεία βίου καλοῦ καὶ ψυχῆς καθαρᾶς καὶ τῆς κατὰ Χριστὸν ἀρετῆς, ἵνα δι’ αὐτῆς ὁδεύσας ὁ νοῦς, τυχεῖν ὧν ὀρέγεται καὶ καταλαβεῖν δυνηθῇ, καθ’ ὅσον ἐφικτόν ἐστι τῇ ἀνθρώπων φύσει περὶ τοῦ Θεοῦ Λόγου μανθάνειν."
      },
      "title": "말씀의 성육신에 관하여",
      "translation": {
        "notes": [],
        "revision_id": "sha256:49d9cc4017118fc554c3e79483f581508888069881fc39106e5edc1a4cc2e1ae",
        "text": "그러나 성경을 탐구하여 참된 지식을 얻으려면 좋은 삶과 깨끗한 영혼, 그리스도를 따르는 덕이 필요합니다. 그 덕을 따라 걸어온 정신이, 인간의 본성으로 하나님의 말씀에 관해 배울 수 있는 만큼, 자신이 갈망하는 것을 얻고 깨달을 수 있게 하려는 것입니다."
      },
      "work_id": "athanasius-incarnation",
      "work_passage_id": "athanasius-incarnation:57.1"
